class TokenBucket:
    def __init__(self, capacity, per_second):
        self.capacity, self.rate = capacity, per_second
        self.tokens, self.last = capacity, 0.0
    def allow(self, now):
        self.tokens = min(self.capacity, self.tokens + (now - self.last) * self.rate)  # refill
        self.last = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False

bucket = TokenBucket(capacity=5, per_second=1)
for n, t in enumerate([0, 0, 0, 0, 0, 0, 1, 1, 6], 1):
    print(f"t={t}s request {n}:", "ok" if bucket.allow(t) else "429 Too Many Requests")
